contracts/AccountRegistrar.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

interface IPowerAsset {
    function mintRegistrationRewards(
        address userAddr,
        address registrationNode
    ) external;
}

contract AccountRegistrar is
    Initializable,
    OwnableUpgradeable,
    ReentrancyGuardUpgradeable,
    EIP712Upgradeable,
    UUPSUpgradeable
{
    using ECDSA for bytes32;

    uint256 public constant SIGNATURE_EXPIRY = 1 hours;

    bytes32 private constant _REGISTRATION_TYPEHASH =
        keccak256(
            "Registration(address userAddr,bytes32 emailHash,uint256 nonce,uint256 chainid,uint256 expireAt)"
        );

    IPowerAsset public powerAsset;

    mapping(address => bytes32) public userEmailHash;
    mapping(bytes32 => address) public emailHashToAddr;
    mapping(address => uint256) public nonces;

    event UserRegistered(address indexed user, bytes32 emailHash);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address _powerAssetAddr) public initializer {
        __Ownable_init(msg.sender);
        __ReentrancyGuard_init();
        __EIP712_init("Aiverse-Account-Registrar", "1");
        __UUPSUpgradeable_init();

        powerAsset = IPowerAsset(_powerAssetAddr);
    }

    function registerByEmail(
        address userAddr,
        bytes32 emailHash,
        bytes memory ownerSignature,
        bytes memory userSignature,
        uint256 expireAt
    ) external onlyOwner nonReentrant {
        require(block.timestamp <= expireAt, "Signature expired");
        require(
            expireAt <= block.timestamp + SIGNATURE_EXPIRY,
            "Expiry too far in future"
        );
        require(userAddr != address(0), "Invalid user address");

        require(
            emailHashToAddr[emailHash] == address(0),
            "Email already registered"
        );
        require(
            userEmailHash[userAddr] == bytes32(0),
            "Address already registered"
        );

        _verifySignature(
            userAddr,
            emailHash,
            ownerSignature,
            owner(),
            expireAt
        );
        _verifySignature(
            userAddr,
            emailHash,
            userSignature,
            userAddr,
            expireAt
        );

        _register(userAddr, emailHash);
    }

    function _verifySignature(
        address userAddr,
        bytes32 emailHash,
        bytes memory signature,
        address expectedSigner,
        uint256 expireAt
    ) internal view {
        bytes32 structHash = keccak256(
            abi.encode(
                _REGISTRATION_TYPEHASH,
                userAddr,
                emailHash,
                nonces[userAddr],
                block.chainid,
                expireAt
            )
        );
        bytes32 digest = _hashTypedDataV4(structHash);
        address recovered = digest.recover(signature);
        require(recovered == expectedSigner, "Invalid signature");
    }

    function _register(address userAddr, bytes32 emailHash) internal {
        nonces[userAddr]++;
        userEmailHash[userAddr] = emailHash;
        emailHashToAddr[emailHash] = userAddr;
        powerAsset.mintRegistrationRewards(userAddr, msg.sender);
        emit UserRegistered(userAddr, emailHash);
    }

    /// @dev UUPS authorization logic
    function _authorizeUpgrade(
        address newImplementation
    ) internal override onlyOwner {}
}

contracts/AiverseCoin.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/proxy/transparent/TransparentUpgradeableProxy.sol";

contract AiverseCoin is
    Initializable,
    ERC20Upgradeable,
    OwnableUpgradeable,
    UUPSUpgradeable
{
    uint256 public constant HALVING_PERIOD_DAYS = 1460;
    uint256 public constant MAX_TOTAL_SUPPLY = 210_000_000_000 ether;

    uint256 public initialDailyReward;
    uint256 public startDay;
    address public stakeController;
    uint256 public lastMintedDay;

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        string memory name_,
        string memory symbol_
    ) public initializer {
        __ERC20_init(name_, symbol_);
        __Ownable_init(msg.sender);
        __UUPSUpgradeable_init();

        startDay = block.timestamp / 1 days;
        initialDailyReward = (MAX_TOTAL_SUPPLY / 2) / HALVING_PERIOD_DAYS;
    }

    function setStakeController(address _stakeController) external onlyOwner {
        stakeController = _stakeController;
    }

    function mintToken() external onlyOwner {
        uint256 currentDay = block.timestamp / 1 days;
        require(currentDay > lastMintedDay, "Already minted for today");

        uint256 amount = getMintAmountByDay(currentDay);
        require(
            totalSupply() + amount <= MAX_TOTAL_SUPPLY,
            "Exceeds max supply"
        );

        lastMintedDay = currentDay;
        _mint(address(this), amount);
    }

    function userClaimToken(address userAddr, uint256 amount) external {
        require(
            msg.sender == stakeController,
            "Only StakeController can transfer"
        );
        _transfer(address(this), userAddr, amount);
    }

    function getMintAmountByDay(uint256 day) public view returns (uint256) {
        require(day >= startDay, "Invalid day");

        uint256 daysSinceStart = day - startDay;
        uint256 halvingEra = daysSinceStart / HALVING_PERIOD_DAYS;

        uint256 reward = initialDailyReward >> halvingEra;
        return reward;
    }

    /// @dev Required by UUPSUpgradeable
    function _authorizeUpgrade(
        address newImplementation
    ) internal override onlyOwner {}
}

